  if(!record(rows)||rows.type!=='array'||!Number.isInteger(rows.minItems)||rows.minItems<1
    ||rows.maxItems!==rows.minItems||!Array.isArray(rows.items?.anyOf)||rows.items.anyOf.length!==rows.minItems)return false;
