import {validateRequest} from './mission-generic-runtime.mjs';
const uuid=x=>typeof x==='string'&&/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(x);
const exact=(x,k)=>x!==null&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).length===k.length&&k.every(n=>Object.hasOwn(x,n));
// Closed internal failure classes; raw RPC text, SQLSTATE and details never leave the service.
const readFailures=new WeakMap();
const transientReadSqlStates=new Set(['08000','08001','08003','08006','08007','40001','40P01','55P03','57014','53300','57P01','57P02','57P03']);
const forbiddenReadCodes=new Set(['42501','28000','28P01','PGRST301','PGRST302','PGRST303']);
export function missionReadError(kind){
 const safe=['transient','forbidden','invalid'].includes(kind)?kind:'invalid',error=Error('MISSION_READ_REJECTED');
 readFailures.set(error,safe);return error;
}
export function classifyMissionReadError(error,status=null){
 if(error&&typeof error==='object'&&readFailures.has(error))return error;
 const code=typeof error?.code==='string'?error.code:'';
 if(forbiddenReadCodes.has(code))return missionReadError('forbidden');
 if(transientReadSqlStates.has(code))return missionReadError('transient');
 if(code!=='')return missionReadError('invalid');
 const network=error?.name==='TypeError'&&/fetch|network|load failed/i.test(String(error?.message??''));
 if(status===0||error?.name==='AbortError'||error?.name==='TimeoutError'||network)return missionReadError('transient');
